shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- a/test/xchar-test.cc
+++ b/test/xchar-test.cc
@@ -440,6 +440,48 @@ TEST(locale_test, localized_double) {
   EXPECT_EQ(fmt::format(loc, "{:8L}", 1230.0), "   1~230");
 }

+TEST(locale_test, localized_double_alignment) {
+  auto loc = std::locale(std::locale::classic(), new special_grouping<char>());
+  loc = std::locale(loc, new special_grouping<wchar_t>());
+  const struct {
+    double value;
+    const char* digits;
+  } cases[] = {{-119.921, "-119.921"}, {2194.139, "2,194.139"},
+               {-57.639, "-57.639"},   {-5.980, "-5.980"},
+               {-2.119, "-2.119"},     {0.295, "0.295"},
+               {1.295, "1.295"},       {0.0, "0.000"},
+               {-0.0, "-0.000"},       {0.000295, "0.000"},
+               {12345.678, "12,345.678"}};
+  for (auto test : cases) {
+    auto digits = std::string(test.digits);
+    auto expected = std::string(19 - digits.size(), ' ') + digits;
+    auto result = fmt::format(loc, "{:19.3Lf}", test.value);
+    EXPECT_EQ(expected, result);
+    EXPECT_EQ(19u, result.size());
+    EXPECT_EQ(std::wstring(expected.begin(), expected.end()),
+              fmt::format(loc, L"{:19.3Lf}", test.value));
+  }
+}
+
+TEST(locale_test, localized_double_alignment_modes) {
+  auto loc = std::locale(std::locale::classic(), new numpunct<char>());
+  EXPECT_EQ("   1?295", fmt::format(loc, "{:8.3Lf}", 1.295));
+  EXPECT_EQ("1?295***", fmt::format(loc, "{:*<8.3Lf}", 1.295));
+  EXPECT_EQ("*1?295**", fmt::format(loc, "{:*^8.3Lf}", 1.295));
+  EXPECT_EQ("0001?295", fmt::format(loc, "{:08.3Lf}", 1.295));
+  EXPECT_EQ("  +1?295", fmt::format(loc, "{:+8.3Lf}", 1.295));
+  EXPECT_EQ("   1?295", fmt::format(loc, "{:8L}", 1.295));
+  EXPECT_EQ("1~234?567***", fmt::format(loc, "{:*<12.3Lf}", 1234.567));
+
+  auto small_loc =
+      std::locale(std::locale::classic(), new small_grouping<char>());
+  EXPECT_EQ("   1,2.345", fmt::format(small_loc, "{:10.3Lf}", 12.345));
+  auto ungrouped_loc =
+      std::locale(std::locale::classic(), new no_grouping<char>());
+  EXPECT_EQ("   1.295", fmt::format(ungrouped_loc, "{:8.3Lf}", 1.295));
+  EXPECT_EQ("   1.295", fmt::format(loc, "{:8.3f}", 1.295));
+}
+
 TEST(locale_test, format) {
PATCH
cmake -B build -S . && cmake --build build --parallel 4 --target xchar-test && build/bin/xchar-test --gtest_filter='locale_test.localized_double_alignment*'

cd /testbed && patch -p1 <<'PATCH'
--- a/include/fmt/format.h
+++ b/include/fmt/format.h
@@ -2637,7 +2637,7 @@
     int num_zeros = fspecs.showpoint ? fspecs.precision - significand_size : 0;
     size += 1 + to_unsigned(num_zeros > 0 ? num_zeros : 0);
     auto grouping = Grouping(loc, fspecs.locale);
-    size += to_unsigned(grouping.count_separators(significand_size));
+    size += to_unsigned(grouping.count_separators(exp));
     return write_padded<align::right>(out, specs, size, [&](iterator it) {
       if (sign) *it++ = detail::sign<Char>(sign);
       it = write_significand(it, significand, significand_size, exp,
--- a/ChangeLog.rst
+++ b/ChangeLog.rst
@@ -1,6 +1,9 @@
 9.1.0 - 2022-08-27
 ------------------

+* Fixed alignment of localized floating-point numbers by counting grouping
+  separators only in the integer part.
+
 * ``fmt::formatted_size`` now works at compile time
PATCH
cmake --build build --parallel 4 --target xchar-test format-test && ctest --test-dir build -V -R '^(xchar|format)-test$'

